// Mehlman HY Immuno
const immunoQuestions = [
  // ===== IMMUNO: MHC + Antigen Presentation =====
  { id: "im1", category: "MHC", q: "MHC I versus MHC II: which cells are they on, which T cell do they interact with, and what do they bind?", a: "MHC I is on ALL nucleated cells (not RBCs) and interacts with CD8+ T cells, binding TCR + CD8. MHC II is on antigen-presenting cells (dendritic cells, macrophages, B cells) and interacts with CD4+ T cells, binding TCR + CD4." },
  { id: "im2", category: "MHC", q: "How is antigen loaded onto MHC I versus MHC II?", a: "MHC I: antigen is associated with beta-2-microglobulin and TAP protein. MHC II: loaded following release of the invariant chain within an acidified endosome." },
  { id: "im3", category: "MHC", q: "Which MHC presents intracellular (cytosolic) versus extracellular (endocytosed) antigen, and why does that make sense?", a: "MHC I presents intracellular antigen (viruses, most intracellular pathogens) to CD8+ cytotoxic T cells, which kill the cell. MHC II presents phagocytosed extracellular antigen to CD4+ helper T cells." },
  // ===== IMMUNO: Lymphocytes =====
  { id: "im4", category: "Lymphocytes", q: "What are the three types of lymphocytes, and what is their common origin?", a: "NK cells, B cells, and T cells - all derived from lymphoid progenitors." },
  { id: "im5", category: "Lymphocytes", q: "How does CD16 on NK cells produce antibody-dependent cell-mediated cytotoxicity (ADCC)?", a: "Plasma B-cell antibodies bind antigen at their Fab regions, leaving Fc regions facing outward. CD16 on the NK cell binds those Fc regions; crosslinking of CD16 makes the NK cell release granzymes, granulysins, and perforins, inducing apoptosis in the target cell.", img: "/qimg/immuno/antibody-fab-fc.webp", alt: "Antibody diagram: antigen binds the Fab region (idiotype, highly specific for antigen); IgM/IgG bind complement at the Fc region (isotype, determines antibody class); macrophages and mast cells also bind Fc" },
  { id: "im6", category: "Lymphocytes", q: "What do you need to know about B cells for the USMLE?", a: "Highest yield: the main cell of humoral immunity - it differentiates into plasma cells that secrete tons of antibodies. It undergoes somatic hypermutation and affinity maturation for increased antibody specificity; proliferates and differentiates in germinal centers of lymph nodes and spleen; it is an APC (can present on MHC II to CD4+ T cells); and most lymphomas and leukemias are B-cell in origin." },
  { id: "im7", category: "Lymphocytes", q: "T cell activation: what are the primary and secondary signals?", a: "Primary signal: MHC binds to TCR + CD molecule (MHC I -> TCR + CD8; MHC II -> TCR + CD4). Secondary signal: B7-1 (CD80) or B7-2 (CD86) on the APC binds CD28 on the naive T cell - this second step is the same for CD4+ and CD8+ T cells. The T cell is now activated.", img: "/qimg/immuno/tcell-activation.webp", alt: "Diagram of T cell activation: MHC on the nucleated cell/APC binds TCR plus CD4/8 on the naive T cell (primary signal), and B7-1/-2 (CD80/86) binds CD28 (second signal)" },
  { id: "im8", category: "Lymphocytes", q: "What happens after a CD8+ versus CD4+ T cell is activated?", a: "CD8+ cytotoxic cells directly kill nucleated cells that have antigen loaded on MHC I. CD4+ helper cells exert a variety of effects depending on their differentiation - their activation usually occurs after differentiation." },
  { id: "im9", category: "Lymphocytes", q: "Which T cells undergo differentiation, and into what?", a: "CD4+ T cells - for the USMLE, differentiation applies to them. Th0 (undifferentiated CD4+) can become Th1, Th2, Th17, and Treg cells. CD8+ cells are more simplistic: they are merely activated to kill." },
  { id: "im10", category: "Lymphocytes", q: "Th1, Th2, Th17, Treg: what does each do?", a: "Th1 stimulates macrophages, which kill phagocytosed pathogens and (if necessary) organize into granulomas. Th2 stimulates B cells to become antibody-producing plasma cells against extracellular pathogens. Th17 stimulates neutrophilic production and recruitment. Treg cells prevent autoimmunity (suppressive).", img: "/qimg/immuno/th0-differentiation.webp", alt: "Diagram of Th0 differentiation into Th1 (IL-12/IFN-gamma stimulate, IL-4/IL-10 inhibit), Th2 (IL-4/IL-10 stimulate, IL-12/IFN-gamma inhibit), Th17 (IL-6/TGF-beta), and Treg (TGF-beta)" },
  { id: "im11", category: "T Cell Differentiation", q: "Th0 to Th1: which cytokines drive it, who secretes them, and what is the HY loop?", a: "IL-12 (secreted by macrophages) and IFN-gamma (secreted by Th1 cells) drive Th0 to Th1. Once a Th1 cell forms, it activates macrophages via IFN-gamma, the macrophages secrete even more IL-12, which stimulates more Th0 to Th1. The IL-12 / IFN-gamma loop is HY for Step 1.", img: "/qimg/immuno/th1-macrophage-loop.webp", alt: "Diagram of the Th1-macrophage loop: macrophage IL-12 drives Th0 to Th1, Th1 secretes IFN-gamma which activates the macrophage to make more IL-12" },
  { id: "im12", category: "T Cell Differentiation", q: "What is a granuloma, and what are its macrophages called?", a: "Dense clusters of organized macrophages that appear if inflammation is chronic. Activated macrophages composing a granuloma are called histiocytes, or epithelioid macrophages. In short: IL-12/IFN-gamma → Th1 lineage → macrophage activation." },
  { id: "im13", category: "T Cell Differentiation", q: "Th0 to Th2: which cytokines drive it, and what is the CD40L step?", a: "IL-4 and IL-10 drive Th0 to Th2. The Th2 cell carries CD40 ligand (CD40L) on its surface, which binds CD40 on the B cell, activating it and driving its differentiation into a plasma cell that makes copious antibodies against extracellular pathogens (humoral immunity). In short: IL-4/IL-10 → Th2 = B-cell activation → plasma cells → antibodies.", img: "/qimg/immuno/th2-bcell-cd40.webp", alt: "Diagram of Th0 to Th2 (IL-4/IL-10): Th2 CD40L binds CD40 on the B cell, which becomes a plasma cell producing antibodies" },
  { id: "im14", category: "T Cell Differentiation", q: "Somatic hypermutation versus affinity maturation versus V(D)J recombination - keep them straight.", a: "Somatic hypermutation: mutation rates in immunoglobulin genes 1,000,000x greater than in other cell lines. Affinity maturation: the result - Fab regions generate increasingly greater affinity for pathogens. Both are PLASMA B-cell processes. Do not confuse them with V(D)J recombination, which happens EARLY in B- and T-cell maturation to generate a diverse array of antibodies and TCRs." },
  { id: "im15", category: "T Cell Differentiation", q: "How do the Th1 and Th2 pathways suppress each other (arrows)?", a: "They are in opposition: IL-12/IFN-gamma → ↑Th1 lineage + ↓Th2 lineage; IL-4/IL-10 → ↑Th2 lineage + ↓Th1 lineage." },
  { id: "im16", category: "Thymus", q: "T cell migration through the thymus: what happens in the cortex versus the medulla?", a: "T cells enter the thymic cortex CD4- AND CD8-negative, then become double-positive (both CD4+ and CD8+) still in the cortex. POSITIVE selection occurs in the cortex - only T cells capable of binding self-MHC survive. Migrating into the medulla, they lose either CD4 or CD8. NEGATIVE selection occurs in the medulla - T cells that bind self-antigen too strongly undergo apoptosis, a check against autoimmunity.", img: "/qimg/immuno/thymus-selection.webp", alt: "Diagram of T cell maturation: bone marrow precursor enters the thymic cortex (positive selection, becomes CD4+CD8+), then the thymic medulla (negative selection, loses CD4 or CD8), then migrates to the lymph node" },
  { id: "im17", category: "Thymus", q: "After the thymic medulla, where does a CD8+ T cell go and what does it bind?", a: "It leaves for the lymph node, where it becomes a cytotoxic T cell, binding MHC I on all nucleated cells via its TCR." },
  
  { id: "im18", category: "Cell-Mediated vs Humoral", q: "Which immunity covers which pathogens: most viruses and Listeria; TB / M. leprae / Leishmania / Pneumocystis / Candida; most bacteria and poliovirus?", a: "Most viruses + Listeria (cytoplasm) -> CD8+ T cell, which induces apoptosis of the infected cell. TB, M. leprae, Leishmania, Pneumocystis, Candida (vesicles of macrophages) -> Th1 CD4+ T cell + macrophages. Most bacteria + poliovirus (extracellular fluid) -> Th2 CD4+ T cell + B cell (humoral)." },
  { id: "im19", category: "Cell-Mediated vs Humoral", q: "HY disease associations: which do you answer with a deficiency of cell-mediated versus humoral immunity?", a: "For viruses and Listeria, choose cell-mediated immunity; for chronic mucocutaneous candidiasis, choose deficiency of cell-mediated immunity. Choose deficiency of HUMORAL immunity for IgA deficiency and Bruton X-linked agammaglobulinemia (XLA)." },
  { id: "im20", category: "Cell-Mediated vs Humoral", q: "Which cells make up humoral immunity, and how do they interact?", a: "Plasma B cells produce antibody (humoral = antibodies in the killing). B cells are APCs presenting to Th2 CD4+ T cells via MHC II; Th2 cells activate B cells into plasma cells and induce isotype class-switching via CD40L (on Th2) binding CD40 (on B cell)." },
  { id: "im21", category: "Cell-Mediated vs Humoral", q: "Is the cell-mediated versus humoral split strictly CD8+ versus CD4+?", a: "No - CD4+ Th1 cells contribute to CELL-MEDIATED immunity (alongside CD8+ and macrophages), while CD4+ Th2 cells contribute to humoral immunity." },
  { id: "im22", category: "Antibodies", q: "IgM: complement binding, placental crossing, breast milk, structure, and HY points?", a: "IgM binds complement, does NOT cross placenta, NOT in breastmilk. It is the first antibody in primary immune responses, so it indicates ACUTE infection (e.g., choose IgM titers in a neonate for acute congenital toxo). Pentameric = 10 binding sites = greatest avidity. Hyper-IgM syndrome is caused by CD40L deficiency on Th2 CD4+ T cells." },
  { id: "im23", category: "Antibodies", q: "IgE: mast cells, helminths, and the HY syndrome?", a: "IgE sits on mast cells; crosslinking drives type I hypersensitivity with degranulation (histamine, tryptase). Associated with allergies and eosinophilia; increased in helminth infections (activates eosinophils, which kill helminths with major basic protein). Hyper-IgE (Job) syndrome = FATED: abnormal Facies, staphylococcal cold Abscesses, retained deciduous Teeth, hyper-IgE, Dermatologic (eczematoid) findings." },
  { id: "im24", category: "Antibodies", q: "What is IgD's role?", a: "Part of the B-cell receptor. Considered obscure and the least important antibody for the USMLE." },
  { id: "im25", category: "Antibodies", q: "IgG: complement, placenta, serum levels, and HY points?", a: "IgG binds complement and CROSSES the placenta. It dominates secondary immune responses (re-infections) and chronic infections, has the greatest affinity for antigen, and is the most abundant antibody in serum (~80%). Used in passive immunity (RhoGAM, HepB/VZV IVIG). Its placental crossing causes hemolytic disease of the newborn." },
  { id: "im26", category: "Antibodies", q: "IgA: where is it found and what is its structure?", a: "Most common antibody in mucosal secretions, respiratory tract, and GI tract; the antibody in breastmilk. Secreted as a dimer joined by a J-chain (a pedantic detail that shows up on USMLE). Peyer's patches (GALT) are the predominant source of IgA-producing cells. Does not bind complement or cross placenta." },
  { id: "im27", category: "Antibodies", q: "IgA deficiency - the full HY picture?", a: "Most common hereditary immunodeficiency: recurrent sinopulmonary infections, atopy (seasonal allergies, asthma, eczema), increased risk of Giardia, association with other autoimmune disorders (e.g., vitiligo), and anaphylaxis with blood transfusion. Answers are often just 'deficiency of humoral immunity' or 'deficiency of mucosal immunoglobulin.' Also causes FALSE-NEGATIVE celiac screening (anti-tissue transglutaminase is IgA); celiac patients have 15x greater prevalence of concurrent IgA deficiency." },
  { id: "im28", category: "Passive vs Active Immunity", q: "Passive versus active immunity: acquisition, onset, duration?", a: "Passive: receiving pre-formed antibodies - fast onset (minutes to hours), short duration (weeks, dependent on Ab half-life). Active: real-life exposure to antigen - slow onset (hours to days), long duration (memory cells)." },
  { id: "im29", category: "Passive vs Active Immunity", q: "HY examples of passive versus active immunity?", a: "Passive: post-exposure IVIG for HepB, VZV, tetanus, botulism, diphtheria, rabies; IgA in breastmilk; transplacental IgG. Active: vaccinations and real-life infection." },
  { id: "im30", category: "Complement", q: "Complement: what is it, and what are the two ways it kills or clears targets?", a: "Complement proteins are acute phase proteins made by the liver. Three activation pathways all lead to target cell death via the membrane attack complex (MAC, C5b-C9) or to opsonization and phagocytosis." },
  { id: "im31", category: "Complement", q: "The three complement activation pathways?", a: "Classic: C1 binds the Fc region of IgM and IgG. Alternative: C3b binds directly to the microbial cell surface. Lectin: mannose-binding lectin binds the microbial cell surface. All converge on MAC formation (C5b-C9) or opsonization/phagocytosis." },
  { id: "im32", category: "Complement", q: "Which molecules are the immune system's two major opsonins, and why is IgM NOT one?", a: "C3b and IgG are the two major opsonins. Although IgM and IgG both bind complement, phagocytes have no Fc receptor for IgM, making IgM a poor opsonin." },
  { id: "im33", category: "Complement", q: "What happens to C3 in post-streptococcal glomerulonephritis?", a: "C3 goes down (consumed) in post-strep glomerulonephritis." },
  { id: "im34", category: "Complement", q: "C1 esterase inhibitor deficiency versus paroxysmal nocturnal hemoglobinuria?", a: "C1 esterase INHIBITOR deficiency causes hereditary angioedema. PNH is caused by increased complement-mediated lysis of RBCs from deficiency of the GPI anchor, which anchors CD55 (decay-accelerating factor) and protectin (CD59) to the RBC surface - CD55/59 normally protect RBCs from complement-mediated lysis." },
  { id: "im35", category: "Antigens", q: "Thymus-independent versus thymus-dependent antigens - and which molecules can induce a T cell response?", a: "Thymus-independent antigens are not displayed on MHC, so no T cell response. Thymus-dependent antigens are displayed on MHC with a T cell response. Only PROTEINACEOUS antigens are displayed on MHC - if asked what molecule could induce a T cell response, pick the protein (even odd ones like flagellin or the poly-D-glutamic acid capsule of B. anthracis), not LPS or the polysaccharide capsule of H. influenzae type B. Non-protein antigens need conjugation to a protein to generate a T cell response; thymus-dependent responses produce memory cells, so immunity is longer-lived." },
  { id: "im36", category: "Cytokines", q: "Which cytokines do macrophages secrete, and which stimulates T cells?", a: "Macrophages secrete most importantly TNF-alpha, IL-1, IL-6, IL-8, and IL-12. IL-2 is a T cell stimulator. IL-8 is a neutrophilic chemotactic molecule. Interferons broadly help kill viral infections by inhibiting viral replication." },
  { id: "im37", category: "Cytokines", q: "Which cytokines cause sepsis findings - low BP versus fever?", a: "TNF-alpha and IL-1 are the two associated with sepsis: TNF-alpha causes low BP (increased vascular permeability, decreased systemic vascular resistance); IL-1 causes fever. If forced to pick one cytokine for septic shock, choose TNF-alpha." },
  { id: "im38", category: "Cytokines", q: "IL-1 beyond fever: bone, and the NSAID question?", a: "IL-1 is osteoclast-activating factor - contributes to osteoporosis and lytic bone lesions in metastases and multiple myeloma (a pic of an osteoporotic vertebra can have the answer 'increased IL-1 activity'). Note: if the Q says an NSAID decreases fever, the molecule responsible for fever is PROSTAGLANDIN, not IL-1." },
  { id: "im39", category: "Cytokines", q: "IL-2 and the HY drugs that target it?", a: "IL-2 broadly stimulates T cells. Cyclosporin and tacrolimus decrease transcription of IL-2 by inhibiting calcineurin; sirolimus decreases responsiveness to IL-2. Aldesleukin is recombinant IL-2 used to treat RCC and metastatic melanoma." },
  { id: "im40", category: "Cytokines", q: "IL-3, IL-5, IL-6 - one line each?", a: "IL-3 stimulates myeloid lineage (mostly neutrophils; think GM-CSF-like). IL-5 stimulates eosinophil maturation. IL-6 stimulates acute-phase protein release from the liver (CRP, hepcidin) and can also cause osteoporosis." },
  { id: "im41", category: "Cytokines", q: "IL-10: role and exam answer?", a: "HY anti-inflammatory cytokine that suppresses various immune responses. If asked which cytokine decreases an immune response, choose IL-10 (or TGF-beta). With IL-4 it drives Th0 to Th2, supporting humoral immunity." },
  { id: "im42", category: "Cytokines", q: "IL-11 and its recombinant drug?", a: "IL-11 stimulates platelets. Oprelvekin is recombinant IL-11 used to stimulate thrombopoiesis post-chemotherapy." },
  { id: "im43", category: "Cytokines", q: "IL-12 and IFN-gamma: the loop, NK cells, and the deficiency syndrome?", a: "IL-12 and IFN-gamma both drive Th0 to Th1 and inhibit Th2. IL-12 stimulates Th1 cells to make IFN-gamma; IFN-gamma (made by Th1) stimulates macrophages, which make IL-12. IL-12 also stimulates NK cells. IL-12 receptor deficiency → less IFN-gamma → less macrophage activity → increased TB infections; treat with IFN-gamma. IFN-gamma also treats NADPH oxidase deficiency (chronic granulomatous disease)." },
  { id: "im44", category: "Cytokines", q: "IFN-beta and TGF-beta: clinical uses and effects?", a: "IFN-beta is used between flares of multiple sclerosis to decrease recurrence (steroids for acute flares). TGF-beta is anti-inflammatory like IL-10, and with IL-6 drives Th0 to Th17." },
  { id: "im45", category: "Cell Surface Markers", q: "CD1a, CD3, CD4, CD5+CD23, CD8, CD10 - quick markers?", a: "CD1a: Langerhans cell histiocytosis (lytic lesions; Birbeck 'tennis racquet' granules on biopsy). CD3: generic T cell marker, associated with the TCR. CD4: T helper marker (Th0/Th1/Th2/Th17/Treg), binds MHC II. CD5+CD23: seen in CLL. CD8: cytotoxic T cells, binds MHC I. CD10: associated with ALL." },
  { id: "im46", category: "Cell Surface Markers", q: "CD14: what does it do, and what is the HY distinction in septic shock?", a: "CD14 is on macrophages, associated with toll-like receptor 4. Binding of lipid A of LPS (endotoxin) to CD14 triggers macrophage release of TNF-alpha + IL-1 → septic shock from endotoxin. Do not confuse with S. aureus TSST superantigen bridging TCR and MHC II → toxic shock syndrome." },
  { id: "im47", category: "Cell Surface Markers", q: "CD15+CD30, CD16+CD56, CD18 - markers and mechanisms?", a: "CD15+CD30: Reed-Sternberg B cells in Hodgkin disease. CD16+CD56: NK cells - CD16 binds the Fc region of IgG causing antibody-dependent cell-mediated cytotoxicity; CD56 is a specific NK marker. CD18: subunit of LFA-1 integrin on WBCs; its deficiency causes leukocyte adhesion deficiency." },
  { id: "im48", category: "Cell Surface Markers", q: "CD19+CD20, CD21, CD25, CD28 - markers?", a: "CD19+CD20: specific B cell markers (rituximab targets CD20; a virus invading CD19/20+ cells = EBV). CD21: receptor for EBV entry into B cells. CD25: Treg marker. CD28: on T cells, bound by B7-1/7-2 (CD80/86) on APCs as the secondary signal after the MHC primary interaction." },
  { id: "im49", category: "Cell Surface Markers", q: "CD34, CD40, CD55+CD59, CD80+CD86 - markers?", a: "CD34: ubiquitous on hematopoietic stem cells. CD40: on B cells; CD40L-CD40 drives isotype class-switching and plasma cell differentiation (CD40L deficiency = hyper-IgM syndrome). CD55+CD59: deficient in PNH. CD80+CD86 (B7-1/7-2): on nucleated cells/APCs, bind CD28 on T cells as secondary signal." },
  { id: "im50", category: "Autoantibodies", q: "Antiphospholipid syndrome: antibodies and HY presentations?", a: "Anti-beta-2-microglobulin, anti-cardiolipin, lupus anticoagulant (the latter is the name for either of the former two if the patient has SLE). Presents as in-vivo thromboses despite an INCREASED in-vitro aPTT; associated with recurrent miscarriage; can cause false-positive syphilis screening." },
  { id: "im51", category: "Autoantibodies", q: "Bullous pemphigoid: antibody, IF pattern, blister level, exam signs?", a: "Anti-hemidesmosome (bullous pemphigoid antigen); hemidesmosomes connect dermis to epidermis at the basement membrane. LINEAR immunofluorescence on skin biopsy; SUB-epidermal blisters; usually no oral involvement; NO Nikolsky sign." },
  { id: "im52", category: "Autoantibodies", q: "Pemphigus vulgaris: antibody, IF pattern, blister level, exam signs?", a: "Anti-desmosome (anti-desmoglein 1 and 3); desmosomes connect adjacent epidermal cells side-to-side. NET-LIKE immunofluorescence; INTRA-epidermal blisters; oral involvement can be present; POSITIVE Nikolsky sign (skin sloughs with friction)." },
  { id: "im53", category: "Autoantibodies", q: "Goodpasture syndrome: antibody, presentation, and the Alport distinction?", a: "Anti-collagen IV (anti-GBM); linear immunofluorescence on renal biopsy since collagen IV lines basement membranes. Presents as a male in his 20s-40s with hematuria + hemoptysis. Don't confuse with Alport syndrome: XR mutation in type IV collagen (not antibody), male with red urine + eye/ear problems." },
  { id: "im54", category: "Autoantibodies", q: "Granulomatosis with polyangiitis (Wegener): antibody and presentation?", a: "c-ANCA (anti-proteinase 3). Presents as hematuria + hemoptysis + head problems (nasal septal perforation, mastoiditis, sinusitis, necrotizing otitis); sometimes mononeuritis multiplex." },
  { id: "im55", category: "Autoantibodies", q: "Eosinophilic granulomatosis with polyangiitis (Churg-Strauss) versus microscopic polyangiitis?", a: "Churg-Strauss: p-ANCA (anti-myeloperoxidase), asthma + eosinophilia. Microscopic polyangiitis: p-ANCA (anti-MPO), usually just red urine. Both can have mononeuritis multiplex." },
  { id: "im56", category: "Autoantibodies", q: "SLE: the antibody list and the HY exam points?", a: "Anti-dsDNA (rises in acute flares, best reflects renal prognosis), anti-Smith (more specific - rules in SLE if present), anti-hematologic cell line antibodies, lupus anticoagulant. Thrombocytopenia is exceedingly HY; if all cell lines are down, choose 'increased peripheral destruction,' not aplastic anemia. Most common presenting feature overall is ARTHRITIS (malar rash appears in only ~1/3 of questions). C3 can fall in flares. Lupus nephritis on NBME is almost always diffuse proliferative glomerulonephritis (DPGN)." },
  { id: "im57", category: "Autoantibodies", q: "Drug-induced lupus: antibody and culprit drugs?", a: "Anti-HISTONE antibodies. Drugs (Mom is HIPP): Minocycline, Hydralazine, INH, Procainamide, Penicillamine. Presents as arthritis + pericarditis or mediastinitis in someone given one of these meds." },
  { id: "im58", category: "Autoantibodies", q: "Myasthenia gravis versus Lambert-Eaton: antibodies, presentation, treatment?", a: "MG: post-synaptic NICOTINIC acetylcholine receptor antibodies; sometimes paraneoplastic of thymoma; 40s woman with diplopia, eyelid ptosis, dysphagia/hoarseness, WORSE with activity; Tx is pyridostigmine. Lambert-Eaton: PRE-synaptic voltage-gated calcium channel antibodies; sometimes paraneoplastic of small cell lung cancer; proximal weakness that IMPROVES with activity." },
  { id: "im59", category: "Autoantibodies", q: "Small cell cerebellar dysfunction and polymyositis/dermatomyositis: antibodies and presentation?", a: "SCLC cerebellar: anti-Hu / anti-Yo; ataxia with small cell lung cancer and NEGATIVE CNS imaging. PM/DM: anti-Jo1; proximal weakness + increased serum CK; sometimes paraneoplastic of ovarian cancer. Dermatomyositis = polymyositis + skin findings (shawl rash, Gottron papules, mechanic's hands, heliotrope)." },
  { id: "im60", category: "Autoantibodies", q: "Limited versus diffuse systemic sclerosis (scleroderma): antibodies and findings?", a: "Limited (CREST: Calcinosis, Raynaud, Esophageal dysmotility, Sclerodactyly, Telangiectasias): anti-centromere. Diffuse: anti-topoisomerase I (Scl-70), can add malignant HTN (~220/120) from renal involvement driving a RAAS surge. Pulmonary fibrosis leading to pulmonary HTN is HY for BOTH types." },
  { id: "im61", category: "Autoantibodies", q: "Primary biliary cirrhosis versus autoimmune hepatitis: antibodies and presentations?", a: "PBC: anti-mitochondrial; woman 20s-50s with increased ALP, direct bilirubin, and cholesterol, generalized pruritis, and personal/family history of other autoimmune disease (RA, SLE). Autoimmune hepatitis: anti-smooth muscle; woman 20s-30s with idiopathic transaminase elevation; a diagnosis of exclusion." },
  { id: "im62", category: "Autoantibodies", q: "Rheumatoid arthritis and Sjogren: antibodies?", a: "RA: rheumatoid factor (an IgM against the Fc region of IgG) and anti-cyclic citrullinated peptide (anti-CCP), which is more specific than RF. Sjogren: anti-SS-A (anti-Ro) and anti-SS-B (anti-La); presents as xerostomia + xerophthalmia + arthritis." },
  { id: "im63", category: "Autoantibodies", q: "Graves versus Hashimoto: antibodies and HY findings?", a: "Graves: anti-TSH receptor (thyroid-stimulating immunoglobulin, TSI); most common cause of hyperthyroidism; exophthalmos and pretibial myxedema are HY. Hashimoto: anti-thyroperoxidase (anti-microsomal) and anti-thyroglobulin; highest-yield cause of hypothyroidism in Western countries (worldwide: iodine deficiency); lymphocytic infiltrate on biopsy." },
  { id: "im64", category: "Autoantibodies", q: "Hashimoto thyroiditis - the non-obvious NBME findings?", a: "Beyond the buzzy ones (weight gain, brittle hair, dry doughy skin, cold intolerance), HY findings: bradycardia 55-60, menstrual irregularity, dysthymia/depression/apathy, carpal tunnel syndrome (GAG deposition), increased cholesterol, proximal muscle weakness with increased CK (hypothyroid myopathy), and even transaminitis." },
  { id: "im65", category: "Autoantibodies", q: "Pernicious anemia and celiac disease: antibodies?", a: "Pernicious anemia: anti-parietal cell or anti-intrinsic factor antibodies; presents as B12 deficiency (intrinsic factor is needed to absorb B12 at the terminal ileum). Celiac: anti-endomysial (anti-gliadin) and anti-tissue transglutaminase IgA (screening is falsely negative with concurrent IgA deficiency); insensitivity to wheat, oats, rye, barley; duodenal biopsy shows villous flattening; can present with iron deficiency anemia." },
  { id: "im66", category: "Autoantibodies", q: "Type 1 diabetes and primary membranous glomerulonephritis: antibodies?", a: "T1DM: anti-glutamic acid decarboxylase (anti-GAD) and anti-zinc transporter 8. Primary membranous GN: anti-phospholipase A2 receptor; it is a nephrotic syndrome - other HY causes are drugs (gold salts, dapsone, sulfonamides), autoimmune disease (RA), cancer (pancreatic, breast), and hepatitis B." },
  { id: "im67", category: "Autoantibodies", q: "TTP versus ITP: antibodies and presentations?", a: "TTP: anti-ADAMTS13 (a metalloproteinase that cleaves vWF multimers); pentad of thrombocytopenia, schistocytosis (together = MAHA), renal issues, fever, neurologic signs. ITP: anti-GpIIb/IIIa on platelets; classically a school-age kid with petechiae or nosebleeds after a viral infection, or a woman 30s-40s with increased bleeding time and low platelets." },
  { id: "im68", category: "Autoantibodies", q: "HIT versus Addison versus rheumatic heart disease: antibodies?", a: "HIT: anti-PF4-heparin antibodies; thrombocytopenia after heparin; treat with a direct thrombin inhibitor (dabigatran), warfarin is wrong. Addison: sometimes anti-21-hydroxylase; low Na, high K, low bicarb/pH, high ACTH, hyperpigmentation. Rheumatic heart disease: anti-myosin and anti-valve-protein antibodies formed against Group A Strep M protein that cross-react with the mitral valve (molecular mimicry)." },
  { id: "im69", category: "Autoantibodies", q: "Rheumatic heart disease - the HY clinical details?", a: "Type II hypersensitivity (don't confuse with PSGN, which is type III). Mitral regurgitation early, mitral stenosis late. Sydenham chorea is the autoimmune basal ganglia condition; erythema marginatum is the characteristic skin finding." },
  { id: "im70", category: "Autoantibodies", q: "Neuromyelitis optica (Devic syndrome) versus MS?", a: "Anti-aquaporin 4 antibodies (asked on 2CK Neuro form). Presents basically like MS except the antibodies are positive and CSF is negative for IgG oligoclonal bands." },
  { id: "im71", category: "Autoantibodies", q: "Cold versus warm autoimmune hemolytic anemia?", a: "Cold: IgM against RBCs (think ice cream = cold); HY associations CMV and Mycoplasma. Warm: IgG against RBCs; caused by miscellaneous drugs and infections; associated with CLL. Both are Coombs positive (antibodies against RBCs)." },
  { id: "im72", category: "Hemolytic Disease of the Newborn", q: "Rh-type hemolytic disease of the newborn: mechanism and severity?", a: "Rh(-) mom in a first pregnancy is exposed to Rh(+) fetal blood and makes anti-Rh antibodies; in a subsequent pregnancy, IgG against Rh crosses the placenta and hemolyzes fetal Rh(+) RBCs. Severity ranges from fatal in utero with fetal hydrops to mere pathologic jaundice in the neonate." },
  { id: "im73", category: "Hemolytic Disease of the Newborn", q: "ABO-type HDN - how does the USMLE frame it?", a: "Most anti-A/anti-B antibodies are IgM, but O-blood people have fractionally more IgG; transplacental IgG attacks fetal RBCs. USMLE gives an O+ MOM in her FIRST pregnancy with an A or B fetus - that frames ABO-type HDN specifically (versus O- Rh- mom in a second pregnancy for Rh type)." },
  { id: "im74", category: "Transfusion Reactions", q: "Febrile non-hemolytic transfusion reaction: mechanism, Coombs status, prevention?", a: "Recipient antibodies activate donor WBCs, which release cytokines → fever and chills within ~2 hours. Mechanism is written as 'preformed antibodies against donor leukocyte antigens' or 'cytokine release from transfused blood.' Coombs NEGATIVE (no antibodies against RBCs). Leukoreduction mitigates risk by reducing donor WBCs." },
  { id: "im75", category: "Transfusion Reactions", q: "Acute hemolytic (ABO mismatch) transfusion reaction: mechanism and vignette?", a: "Recipient antibodies against A/B antigens on donor RBCs → agglutination and intravascular hemolysis (LDH rises; RBCs are packed with LDH), with complement activation. Vignette: fever, chills, flank pain within MINUTES, often an 'impending sense of doom' 10 minutes in; transfusion is stopped and the next best step is the antiglobulin (Coombs) test - POSITIVE here." },
  { id: "im76", category: "Transfusion Reactions", q: "Delayed transfusion reaction: antigens, timing, lab answer?", a: "Recipient antibodies against MINOR antigens on donor RBCs (Rh, Kell, Duffy, Kidd). Vignette: surgery with intraoperative RBCs, then hemoglobin gradually falls over the following week. Answer: Coombs positive, unconjugated bilirubin." },
  { id: "im77", category: "Transfusion Reactions", q: "TRALI: presentation and mechanism?", a: "The answer for an ARDS-like presentation with bilateral crackles and low O2 sats UNDER 6 hours after a transfusion. Mechanism: abnormal priming of neutrophils in the lung reacting to cytokines in transfused blood products. Technically NON-cardiogenic pulmonary edema." },
  { id: "im78", category: "Transfusion Reactions", q: "TACO versus TRALI - how do you tell them apart on the vignette?", a: "TACO (transfusion-associated circulatory overload, aka transfusion-induced hypervolemia) is CARDIOGENIC pulmonary edema - the left heart can't handle the increased hydrostatic pressure, causing transudation into alveoli. Two framings: (1) a patient with heart failure/MI history who gets respiratory distress after repeated blood products (NBME: 72-yr-old with old MI, bilateral crackles 30 minutes after 4 packs of RBCs); (2) no cardiac history mentioned but a TRALI-sounding vignette MORE than 6 hours post-transfusion." },
  { id: "im79", category: "Hypersensitivity", q: "Type I hypersensitivity: mechanism and examples?", a: "Immediate (minutes): antigen binds the Fab region of IgE on mast cells/basophils, crosslinking adjacent IgE → degranulation with histamine + tryptase. Late (hours): cytokines recruit inflammatory cells (eosinophils). Examples: anaphylaxis (bee sting, peanut allergy), atopy/asthma." },
  { id: "im80", category: "Hypersensitivity", q: "Type II hypersensitivity: mechanism and examples?", a: "Antibody production against one's own cells, tissues, receptors. Examples: Graves, Hashimoto, Goodpasture, pernicious anemia, HIT, ITP, rheumatic fever, myasthenia gravis, Lambert-Eaton, bullous pemphigoid, pemphigus vulgaris." },
  { id: "im81", category: "Hypersensitivity", q: "Type III hypersensitivity: mechanism and examples?", a: "Antibody-antigen complexes that deposit (the antibodies don't target cells/tissues/receptors directly). Examples: post-streptococcal glomerulonephritis, polyarteritis nodosa, SLE, Arthus reaction, serum sickness." },
  { id: "im82", category: "Hypersensitivity", q: "Type IV hypersensitivity: mechanism and examples?", a: "T cell response - the only type NOT associated with antibodies; mediated by CD8+ or CD4+ T cells. Examples: PPD skin test for TB, contact dermatitis (poison ivy/oak/sumac, sunscreen, nickel on watches, latex), graft-versus-host disease." },
  { id: "im83", category: "Vaccines", q: "Killed vaccines: which ones, and what response do they generate?", a: "RabIes, Influenza (IM), Polio (Salk, IM), Pertussis, Hep A - 'RIPP Always.' They generate a humoral (antibody) response via expression on MHC II after phagocytosis by APCs, since they can't invade nucleated cells for MHC I expression." },
  { id: "im84", category: "Vaccines", q: "Live-attenuated vaccines: which ones, response, and safety rules?", a: "Yellow fever, varicella, rotavirus (oral), influenza (intranasal), polio (Sabin, oral), MMR, typhoid (oral). They are expressed on MHC I by nucleated cells, generating a CD8+ T cell response. MMR and varicella can be given in HIV if CD4 >200 cells/uL. AVOID live vaccines in pregnancy." },
  { id: "im85", category: "Vaccines", q: "Recombinant and toxoid vaccines?", a: "Recombinant: HPV, HBV. Toxoid: diphtheria, tetanus." },
  { id: "im86", category: "Immunodeficiencies", q: "SCID: genetics, presentation, treatment?", a: "X-linked recessive most common (common gamma chain / IL-2 receptor mutation); autosomal recessive type is ADA deficiency. Combined T + B cell deficiency: absent thymic shadow plus scanty/absent lymph nodes and tonsils. Sick kid 1-5 years old with infections of ALL types (viral, fungal, bacterial, protozoal) since birth. Tx: bone marrow transplant." },
  { id: "im87", category: "Immunodeficiencies", q: "Bruton XLA versus SCID - how does the vignette separate them?", a: "XLA: XLR mutation in Bruton tyrosine kinase; isolated B cell deficiency; scanty/absent lymph nodes and tonsils; decreased immunoglobulins of ALL classes. The vignette is a boy with ONLY BACTERIAL infections since ~6 months of age - mention of viral, fungal, or protozoal infections makes it SCID instead." },
  { id: "im88", category: "Immunodeficiencies", q: "Bruton XLA: NBME treatment and usual answer phrasing?", a: "Tx on NBME is 'monthly infusion of immunoglobulin.' The answer will often be 'deficiency of humoral immunity' rather than 'Bruton XLA.'" },
  { id: "im89", category: "Immunodeficiencies", q: "IgA deficiency - vignette and odd HY extras?", a: "Recurrent sinopulmonary infections typically between high school and 30s (sore cheek = sinusitis + pneumonia history). Ultra-HY extras: anaphylaxis with transfusion, Giardia history, atopy (asthma, seasonal allergies, eczema), associations with vitiligo and celiac, falsely negative celiac antibody screen, and even false-POSITIVE pregnancy tests (heterophile antibody production - no relation to EBV). Answers often: 'deficiency of mucosal immunoglobulin' or 'deficiency of humoral immunity.'" },
  { id: "im90", category: "Immunodeficiencies", q: "DiGeorge syndrome: genetics, embryology, findings?", a: "T cell deficiency from 22q11 deletion - failure of the 3rd and 4th pharyngeal POUCHES (3rd → thymus + two inferior parathyroids; 4th → two superior parathyroids). Absent thymic shadow; hypocalcemia from hypoparathyroidism (Chvostek and Trousseau signs). HY cardiac anomalies: Tetralogy of Fallot and truncus arteriosus; cleft lip/palate may or may not be mentioned. Antibody levels are NORMAL (choose normal Ab levels even though T cells activate B cells)." },
  { id: "im91", category: "Immunodeficiencies", q: "Chronic mucocutaneous candidiasis?", a: "T cell dysfunction - choose 'deficiency of cell-mediated immunity.' Recurrent candidal skin infections since birth, associated with other autoimmune disease (T1DM, thyroiditis). NBME stem: 17-year-old girl + candidal skin infections since birth + autoimmune thyroiditis + T1DM." },
  { id: "im92", category: "Immunodeficiencies", q: "CGD: defect, organisms, and diagnosis?", a: "NADPH oxidase deficiency, usually X-linked recessive; NADPH oxidase is the 1st enzyme of the respiratory burst (O2 → superoxide), so patients can't synthesize enough H2O2 to overwhelm CATALASE-POSITIVE organisms: Serratia, Pseudomonas, Aspergillus, Candida, E. coli, Staph, H. pylori, Burkholderia (~50% of questions use S. aureus). Diagnose with the dihydrorhodamine test - nitroblue tetrazolium is the atavistic wrong answer when both are listed." },
  { id: "im93", category: "Immunodeficiencies", q: "Myeloperoxidase deficiency, and how the exam separates it from CGD?", a: "Autosomal recessive; MPO is the LAST enzyme of the respiratory burst (H2O2 → hydroxyl-halide radicals, i.e., bleach). One-liner: can't produce hydroxyl-halide radicals / 'impaired conversion of hydrogen peroxide to hypochlorous acid.' Presents with mixed S. aureus + Candida - in a 6-year-old girl with an AR disorder, choose MPO deficiency over CGD (CGD is ~70% XR, and childhood-onset CGD is usually XR)." },
  { id: "im94", category: "Immunodeficiencies", q: "Wiskott-Aldrich syndrome: gene, triad, immunoglobulins?", a: "X-linked recessive (WAS gene); T cell cytoskeletal dysfunction. Triad: immunodeficiency, eczematoid skin lesions, thrombocytopenia. Increased IgA and IgE; decreased IgM. NBME: 12-month-old + Pneumocystis + nosebleeds + eczema → dysfunctional cell = T cell; answer can also be 'deficiency of cell-mediated immunity.'" },
  { id: "im95", category: "Immunodeficiencies", q: "Leukocyte adhesion deficiency?", a: "CD18/LFA-1 integrin deficiency - WBCs can't leave blood vessels for sites of infection, so decreased pus. Classic: delayed separation of the umbilical cord (~50% of questions); the other half say 'absent pus/neutrophils in the skin.' Answer can be 'defective leukocyte chemotaxis.'" },
  { id: "im96", category: "Immunodeficiencies", q: "Chediak-Higashi syndrome?", a: "Phagolysosomal fusion disorder with disrupted microtubule function. Melanosome function also impaired → partial albinism (fairer skin than siblings). Giant granules in phagocytes." },
  { id: "im97", category: "Immunodeficiencies", q: "Ataxia-telangiectasia?", a: "AR failure of double-stranded DNA break repair. Cerebellar atrophy → ataxia; telangiectasias; increased susceptibility to radiation → increased risk of leukemia and lymphoma." },
  { id: "im98", category: "Immunodeficiencies", q: "Hyper-IgM syndrome and Hyper-IgE (Job) syndrome?", a: "Hyper-IgM: CD40L deficiency on CD4+ T cells → decreased CD40 activation on B cells → can't differentiate into plasma cells or class-switch, so antibody is 'stuck' at IgM; vignette is super-elevated IgM, answer 'deficiency of CD40 ligand.' Job (hyper-IgE): FATED - abnormal Facies, staphylococcal cold Abscesses, retained primary Teeth, hyper-IgE, Dermatologic findings." },
  { id: "im99", category: "Immunodeficiencies", q: "IL-12 receptor deficiency?", a: "Recurrent TB infections. Th1 cells lacking the IL-12 receptor can't be activated, don't secrete IFN-gamma, so macrophages aren't activated and granuloma formation decreases - the IL-12/IFN-gamma loop between Th1 cells and macrophages is the key." },
  { id: "im100", category: "Immunodeficiencies", q: "CVID versus IgA deficiency on the vignette?", a: "CVID: normal B cell number but defective maturation into plasma cells → decreased immunoglobulins, not limited to IgA. The adult with recurrent sinopulmonary infections is CVID when immunoglobulin deficiency is broad; if the vignette gives atopy or Giardia, it's IgA deficiency instead." },
  { id: "im101", category: "Immunodeficiencies", q: "Terminal complement deficiency?", a: "C5-C9 deficiency - cannot form the MAC. Recurrent Neisseria infections (gonococcal and meningococcal). The answer is often 'C7' or 'C8' deficiency." },
  { id: "im102", category: "Practice Vignettes", q: "4F has her MHC class I molecules investigated; which process is most likely seen in antigen loading?", a: "Degradation by the proteasome. MHC I loads antigen peptides in the RER before transport to the cell surface with beta-2-microglobulin. Wrong answers - invariant chain association, peptide loading after invariant chain release in an acidified endosome, and binding of endocytic-pathway peptides - all describe MHC II. MHC I is on all nucleated cells (not RBCs) and presents intracellular antigen to CD8+ T cells; MHC II is on APCs (macrophages, dendritic cells, Langerhans cells, B cells) presenting exogenous antigen to CD4+ T cells." },
  { id: "im103", category: "Practice Vignettes", q: "A researcher investigates an immune structure concentrated in endosomes, lysosomes, and phagolysosomes that directly kills organisms (e.g., TB); raising phagolysosomal pH decreases its efficacy. Which process is primarily affected?", a: "MHC II molecule peptide loading. MHC II expresses phagocytosed extracellular antigen, so the endosomal/phagolysosomal pathway is the one involved." },
  { id: "im104", category: "Practice Vignettes", q: "Transgenic rats incapable of expressing beta-2-microglobulin: which host defense is most altered?", a: "Cytotoxic T cells. Beta-2-microglobulin associates with MHC I, which interacts with the T cell receptor on CD8+ cytotoxic T lymphocytes." },
  { id: "im105", category: "Practice Vignettes", q: "4F's thymus is investigated using laser scanning microscopy; what is most likely to be seen?", a: "T lymphocyte antigen receptor selection (thymic positive/negative selection of TCRs)." },
  { id: "im106", category: "Practice Vignettes", q: "3M with bacterial infections since 6 months of age and scanty lymph nodes/tonsils: mechanism?", a: "'Deficiency of humoral immunity.' Diagnosis is X-linked agammaglobulinemia: Bruton tyrosine kinase mutation → decreased B cell function → decreased immunoglobulins." },
  { id: "im107", category: "Practice Vignettes", q: "19F with recurrent sinopulmonary infections since elementary school, asthma, and a history of Giardia: mechanism?", a: "'Deficiency of humoral immunity' or 'deficiency of mucosal immunoglobulin' - the diagnosis is IgA deficiency." },
  { id: "im108", category: "Practice Vignettes", q: "17F with cutaneous candida infections since childhood, 2-year history of T1DM, and autoimmune thyroiditis: diagnosis and mechanism?", a: "Chronic mucocutaneous candidiasis - 'T cell dysfunction' = 'impaired cell-mediated immunity.' Although candida infections occur in diabetes, the durations don't match here, which points to CMC." },
  { id: "im109", category: "Practice Vignettes", q: "2F with numerous skin and oral-mucosa infections since birth: ulcerated lesions, WBC 20,000 (75% neutrophils), biopsy shows NO neutrophils in skin, culture grows S. aureus. Defective production of what?", a: "Integrin - leukocyte adhesion deficiency from deficient CD18/LFA-1 integrin (LFA-1 is an integrin; neutrophils can't exit vessels into tissue, so blood WBC is high but skin has no neutrophils)." },
  { id: "im110", category: "Practice Vignettes", q: "3M with severe S. aureus skin infections since birth, NO pus at infection sites, and leukocytosis even without infection: which mechanism is impaired?", a: "'Leukocyte adhesion and migration' - leukocyte adhesion deficiency. LAD questions need not mention delayed umbilical cord separation; 'defective leukocyte chemotaxis' can be the answer instead of 'LAD.'" },
  { id: "im111", category: "Leukocyte Extravasation", q: "Which molecule mediates margination and rolling of leukocytes - selectin or integrin?", a: "Selectin. Rolling on endothelium uses L-, E-, P-selectins; INTEGRIN is the wrong answer for rolling - integrins (CD18/LFA-1) mediate firm adhesion; PECAM-1 mediates diapedesis; chemotaxis uses IL-8, C5a, LTB-4, kallikrein, platelet-activating factor, and bacterial products." },
  { id: "im112", category: "Practice Vignettes", q: "23F with a week of difficulty walking and blurry vision in the left eye, MRI with white matter lesions in the cerebellum: pathogenesis and attacked cell?", a: "'CD4+ T cells are activated by myelin basic protein' - multiple sclerosis (one proposed mechanism: molecular mimicry after HHV-6 infection). If asked which cell T cells attack: oligodendrocyte in MS, Schwann cell in Guillain-Barre." },
  { id: "im113", category: "Practice Vignettes", q: "45M with bilateral crackles, fever 102F, Legionella in sputum: which mechanism clears the organism from his alveoli?", a: "T cell-mediated immunity. Legionella is facultative intracellular, so CD8+ cell-mediated immunity is integral to clearing it - very HY for Step 1." },
  { id: "im114", category: "Practice Vignettes", q: "29M post-splenectomy now has target cells: loss of what structure?", a: "Red pulp - about 75% of the spleen, which normally clears senescent RBCs." },
  { id: "im115", category: "Spleen", q: "Which three vaccines must an asplenic patient receive, and why?", a: "S. pneumoniae, H. influenzae type B, and N. meningitidis - the encapsulated organisms. Encapsulated organisms are normally cleared by opsonization (C3b and IgG, the two major opsonins) and phagocytosis, a job the spleen performs heavily." },
  { id: "im116", category: "Spleen", q: "What appears on blood smear post-splenectomy (or auto-splenectomy)?", a: "Howell-Jolly bodies (RBC nuclear remnants) and target cells - though target cells usually mean thalassemia; asplenia is the rare cause. White pulp (~25%) is the lymphoid tissue where opsonization and phagocytosis occur." },
  { id: "im117", category: "Spleen", q: "How does the spleen relate to platelets?", a: "Splenomegaly can sequester platelets and cause thrombocytopenia; splenectomy can cause transient thrombocytosis." },
  { id: "im118", category: "Practice Vignettes", q: "16F with fever, confusion, and CSF gram-negative diplococci; her younger brother had the same infection last year: which immune disorder?", a: "'Late component of complement deficiency' - terminal complement deficiency (C6-C9) → defective MAC → recurrent Neisseria infections (meningococcus and gonococcus). The answer may simply be 'C7' or 'C8.'" },
  { id: "im119", category: "Practice Vignettes", q: "7M with three N. meningitidis infections in the past year: what is most likely abnormal?", a: "'Total hemolytic complement activation' - pointing to terminal complement deficiency." },
  { id: "im120", category: "Practice Vignettes", q: "40F on a new myelosuppressive chemo drug: what should be monitored for infectious risk?", a: "Neutrophil counts - agranulocytosis. Also caused by thionamides (propylthiouracil, methimazole), ganciclovir, methotrexate, clozapine, ticlopidine. Presents as mouth ulcers (mucositis), sore throat, and fever, or just a low WBC (e.g., 3000/uL)." },
  { id: "im121", category: "Practice Vignettes", q: "35M with red spots on the shins, joint pain, fatigue, Hep C, and protein/blood in urine: which hypersensitivity type damages the kidney?", a: "Type III - cryoglobulinemia (immunoglobulins / antigen-antibody complexes that precipitate below 37C), causing skin lesions/ulcers, Raynaud phenomenon, muscle pain, and glomerulonephritis." },
  { id: "im122", category: "Practice Vignettes", q: "4F's leukocytes fail to express CD40 ligand; the immunoglobulin that predominates in her serum has which biologic property?", a: "'Complement activation.' Hyper-IgM syndrome: no CD40L on T cells → B cells can't class-switch, so IgM predominates. Distractor properties map to: crossing placenta = IgG, mast cell Fc receptors = IgE, mucosal secretion = IgA, B-cell activation = IgD." },
  { id: "im123", category: "Practice Vignettes", q: "42M with IBD starts a monoclonal antibody trial: what does it most likely target?", a: "Tumor necrosis factor (TNF-alpha) - infliximab, adalimumab, etanercept for IBD unresponsive to NSAIDs and steroids." },
  { id: "im124", category: "Practice Vignettes", q: "38F with RA failing NSAIDs, prednisone, and methotrexate: the next drug blocks which cytokine?", a: "TNF-alpha. Distinct from the IBD question but same target - both are real NBME questions, which underscores the yield." },
  { id: "im125", category: "Practice Vignettes", q: "35F with SLE and diffuse proliferative glomerulonephritis: most likely immunological mechanism?", a: "Anti-DNA/DNA immune complex deposition in the glomeruli." },
  { id: "im126", category: "Lymphatic Drainage", q: "An infection of the dorsolateral foot ascending lymphatically drains to which nodes - and the other HY drainage rules?", a: "Popliteal lymph nodes. Others: testes and ovaries → para-aortic; foregut/midgut/hindgut → celiac/SMA/IMA; cervix + uterine body → external iliac; anal canal above the pectinate line + bladder → internal iliac; anal canal below the pectinate line + scrotum → superficial inguinal. Right arm + right trunk above the diaphragm → right lymphatic duct; entire left side + right side below the diaphragm → thoracic duct (both ducts drain into the subclavian-internal jugular confluence on their side)." },
  { id: "im127", category: "Practice Vignettes", q: "29M with HIV receives a drug that blocks viral entry into the cell: molecular target?", a: "Chemokine receptor - CCR5." },
  { id: "im128", category: "Practice Vignettes", q: "Comparing live-attenuated (Sabin) versus killed (Salk) polio vaccines: what common feature accounts for their efficacy?", a: "Neutralizing antibodies in the circulation. Sabin (oral) additionally enters cells → MHC I expression → CD8+ cell-mediated immunity, with secretory IgA and CD8+ effectors in the gut, circulating IgG and CD8+ effectors, and CD8+ memory T cells. Salk (killed) causes no cell-mediated immunity - only circulating neutralizing IgG." },
  { id: "im129", category: "Practice Vignettes", q: "20F, healthy, with a painful swelling on the chest wall inferior to the right breast that the physician identifies as a nipple: biopsy shows what?", a: "'Epithelial cells' (normal finding) - supernumerary nipples are common in women. Yes, this appears on the NBME for Step 1." },
  { id: "im130", category: "Practice Vignettes", q: "33F with shortness of breath, fever, and sputum with gram-positive diplococci: which enzyme initiates intracellular killing of the organism?", a: "NADPH oxidase (first enzyme of the respiratory burst)." },
  { id: "im131", category: "Practice Vignettes", q: "5-month-old girl with recurrent sinopulmonary infections since birth, hypopigmentation of skin/eyes/hair, and giant granules in neutrophils and eosinophils on smear: diagnosis?", a: "Chediak-Higashi syndrome - phagolysosomal fusion disorder with disrupted microtubule function; melanosome function also impaired (hence the hypopigmentation)." },
  { id: "im132", category: "Practice Vignettes", q: "4F with immunodeficiency, fairer skin than her siblings, and giant granules in phagocytes: diagnosis?", a: "Chediak-Higashi syndrome (same mechanism: phagolysosomal fusion disorder, microtubule dysfunction, impaired melanosomes). Asked as its own NBME item in this form too." },
  { id: "im133", category: "Practice Vignettes", q: "2M with immunodeficiency and delayed separation of the umbilical cord: diagnosis?", a: "Leukocyte adhesion deficiency - deficient LFA-1/CD18 integrin." },
  { id: "im134", category: "Practice Vignettes", q: "2M with viral, fungal, bacterial, and protozoal infections since birth, absent thymic shadow, and scanty/absent lymph nodes and tonsils: diagnosis and genetics?", a: "SCID. The XR type is most common (common gamma-chain / IL-2 receptor mutation); the AR type is adenosine deaminase (ADA) deficiency. Tx is bone marrow transplant." },
  { id: "im135", category: "Practice Vignettes", q: "2M with bacterial infections from ~6 months of age and scanty/absent lymph nodes and tonsils: what is the answer phrasing and the stronger SCID contrast?", a: "'Deficiency of humoral immunity' (Bruton XLA), treated with monthly immune globulin infusions. Stronger contrast: Bruton is bacterial infections ONLY; SCID is all types (viral, fungal, bacterial, protozoal). Note one newer Peds form has Bruton with infections 'since birth,' so the infection-type contrast is the reliable one, not onset timing." },
  { id: "im136", category: "Practice Vignettes", q: "5-month-old boy with severe diarrhea and pneumonia, a decreased-size thymus, Pneumocystis jirovecii isolated, low immunoglobulins, and a NORMAL karyotype: diagnosis?", a: "SCID. DiGeorge is the wrong answer: hypogammaglobulinemia is not reported in DiGeorge, and DiGeorge would show a 22q11 deletion on karyotype." },
  { id: "im137", category: "Practice Vignettes", q: "3M with a sore throat and a grey membrane at the back of the throat: immunization with what would have prevented this?", a: "Toxoid vaccine - Corynebacterium diphtheriae. Classic presentation: grey pseudomembrane in the oropharynx and myocarditis (vignette need not mention them)." },
  { id: "im138", category: "Practice Vignettes", q: "34F in septic shock from a gram-negative rod: what is responsible for her low BP?", a: "'Lipopolysaccharide stimulating production of tumor necrosis factor.' Lipid A of LPS (endotoxin) binds toll-like receptor 4 with CD14 co-receptor on macrophages → cytokine release; IL-1 causes fever, TNF-alpha causes vascular permeability and low BP. Contrast toxic shock syndrome's TSST superantigen, which bridges MHC II and TCR." },
  { id: "im139", category: "Practice Vignettes", q: "16M with nasal packing after a car accident nosebleed now develops low BP: which immunological receptors are bound?", a: "MHC II and TCR - toxic shock syndrome from the packing (TSST superantigen bridge). CD14/TLR4 is the wrong answer; that is endotoxic shock from gram-negative sepsis." },
  { id: "im140", category: "Practice Vignettes", q: "2M with mental retardation, fairer skin than siblings, and a hydroxylase enzyme deficiency: how could this have been prevented?", a: "Routine newborn screening via heel-prick test (PKU - phenylalanine hydroxylase deficiency)." },
  { id: "im141", category: "Practice Vignettes", q: "8-month-old girl with oropharyngeal candidiasis, prior parainfluenza infection, and a 3/6 harsh systolic murmur at the left sternal border: deficiency of what?", a: "T lymphocytes - likely DiGeorge (murmur reflects Tetralogy of Fallot). T cell deficiency causes viral, fungal, and protozoal infections; bacterial infections point to B cell deficiency." },
  { id: "im142", category: "Practice Vignettes", q: "8-day-old newborn with truncus arteriosus, calcium 7 mg/dL, and no thymic shadow: diagnosis?", a: "Hypoparathyroidism - DiGeorge syndrome (3rd and 4th pharyngeal pouch agenesis: 3rd = thymus + inferior parathyroids; 4th = superior parathyroids)." },
  { id: "im143", category: "Practice Vignettes", q: "8-month-old boy with recurrent respiratory infections since birth, hypocalcemia, and a broad nasal bridge: deficiency of what?", a: "T cells - DiGeorge syndrome (22q11 deletion)." },
  { id: "im144", category: "Practice Vignettes", q: "16F with 3 days of pain and pressure over the left cheek, strep pneumonias at ages 6 and 10, and seasonal allergies: diagnosis?", a: "'Impaired humoral immunity' / 'deficiency of mucosal immunoglobulin' - IgA deficiency. Sore cheek = sinusitis; recurrent sinopulmonary infections; also associated with Giardia, autoimmune disease (vitiligo), and atopy (winter cough-variant asthma, spring hay fever, summer eczema); anaphylaxis with transfusion is the rare buzzy one." },
  { id: "im145", category: "Practice Vignettes", q: "3M with recurrent otitis media who just got a tympanostomy tube; mom is HIV-negative: diagnosis?", a: "'Antibody deficiency' - IgA deficiency." },
  { id: "im146", category: "Practice Vignettes", q: "8F with fever and purpuric lesions over the trunk and extremities; her brother died of fulminant meningococcemia: diagnosis?", a: "'Complement system immunodeficiency' - terminal complement deficiency (C5-9) with recurrent Neisseria infections." },
  { id: "im147", category: "Practice Vignettes", q: "18M, African American, with N. meningitidis infection and a similar infection two years ago, no other info: examine for which condition?", a: "'Complement deficiency' (terminal complement). Sickle cell disease is the wrong answer - no reason to suspect asplenia from sickle cell here." },
  { id: "im148", category: "Respiratory Burst", q: "Explain why CGD patients are susceptible specifically to catalase-positive organisms.", a: "The respiratory burst in phagocytes produces hydrogen peroxide and hydroxyl-halide radicals (bleach) to kill microbes. Normal people: H2O2 production far exceeds what catalase(+) organisms can neutralize, so they die. CGD (NADPH oxidase deficiency): less H2O2 than the organism's catalase can handle, so it survives the phagocyte. Catalase(+) mnemonic - C SHAPES: Candida, Serratia, H. pylori, Aspergillus, Pseudomonas, E. coli, S. aureus.", img: "/qimg/immuno/respiratory-burst.webp", alt: "Diagram of the neutrophil respiratory burst: NADPH oxidase makes superoxide, superoxide dismutase makes H2O2, myeloperoxidase makes HOCl bleach to kill bacteria; glutathione pathway regenerates NADPH" },
  { id: "im149", category: "Practice Vignettes", q: "6M with recurrent Staph infections and diarrhea: diagnosis and signature organism detail?", a: "'Neutrophil oxidation burst' defect - chronic granulomatous disease (NADPH oxidase deficiency) with catalase-positive organisms (SPACES: Staph, Pseudomonas, Aspergillus, Candida, E. coli, Serratia). Staph infections are the signature; Aspergillus is the most common fungal infection in CGD; 2CK has a child with Serratia sepsis." },
  { id: "im150", category: "Practice Vignettes", q: "5F with life-threatening Staph infections since 3 months of age, normal WBCs, and normal immunoglobulins: what best establishes the diagnosis?", a: "'NADPH oxidase test' - CGD. If the question gets specific, the dihydrorhodamine test is correct over the tetrazolium blue assay (retired NBME 15/16 for Step 1)." },
  { id: "im151", category: "Practice Vignettes", q: "19M with type 1 diabetes, recurrent yeast infections, and myeloperoxidase deficiency: cause of his infection susceptibility?", a: "'Decreased ability to produce hydroxy-halide radicals' - myeloperoxidase converts hydrogen peroxide into hydroxy-halide radicals (bleach)." },
  { id: "im152", category: "Practice Vignettes", q: "32F with a PPD test showing a large area of induration: which cell type predominates in the induration?", a: "Macrophages - NOT cytotoxic T lymphocytes. Macrophages phagocytose the TB antigen and present it on MHC II to CD4+ T cells; CD8+ cytotoxic T cells interact with antigen on MHC I." },
  { id: "im153", category: "Practice Vignettes", q: "60M on chemotherapy with fever of 102F and a low neutrophil count, already on antibiotics: give what to improve the neutrophil count?", a: "GM-CSF (sargramostim) or G-CSF (filgrastim)." },
  { id: "im154", category: "Practice Vignettes", q: "3-week-old boy with two weeks of respiratory distress after birth; his mom has myasthenia gravis: transplacental transfer of which antibody type?", a: "IgG - the only antibody that crosses the placenta (transient neonatal myasthenia)." },
  { id: "im155", category: "Practice Vignettes", q: "14M with fever, stiff neck, non-blanching purpura, BP 60/35 unresponsive to fluids and norepinephrine: treatment and why NE fails?", a: "Hydrocortisone - Waterhouse-Friderichsen syndrome (hemorrhagic necrosis of the adrenal cortices from meningococcal septicemia). Cortisol normally upregulates alpha-1 receptors on arterioles, permitting NE/Epi to work; without cortisol, pressors fail. Non-blanching rash + meningitis = meningococcus." },
  { id: "im156", category: "Practice Vignettes", q: "1-month-old with diffuse white oral plaques that bleed when scraped plus a papular erythematous diaper rash with satellite lesions: mechanism?", a: "'Decreased T lymphocyte activity' - chronic mucocutaneous candidiasis." },
  { id: "im157", category: "Practice Vignettes", q: "8M with a super-high IgM on his lab report: mechanism?", a: "Deficiency of CD40 ligand on T cells - can't activate CD40 on B cells to induce isotype class-switching; hyper-IgM syndrome." },
  { id: "im158", category: "Practice Vignettes", q: "6F with recurrent Staph abscesses, eczematoid skin lesions, and abnormal dentition: diagnosis?", a: "Hyper-IgE (Job) syndrome - FATED: abnormal Facies, staphylococcal cold Abscesses, retained primary Teeth, hyper-IgE, Dermatologic findings." },
  { id: "im159", category: "Practice Vignettes", q: "12M with an eczematoid lesion on the forehead, nosebleeds, and infection history: which cell is dysfunctional?", a: "T cell - Wiskott-Aldrich syndrome (XR): eczematoid lesions + thrombocytopenia + immunodeficiency." },
  { id: "im160", category: "Practice Vignettes", q: "3F with dilated superficial blood vessels on the face and a wobbly gait: mechanism?", a: "'Failure of double-stranded DNA break repair' - ataxia-telangiectasia." },
  { id: "im161", category: "Practice Vignettes", q: "17M with 3 weeks of lymphadenopathy, fever, loose stools, hepatosplenomegaly, low RBCs and WBCs, and HIGH IgM and IgG: diagnosis?", a: "HIV infection. Eliminate CVID, IgA deficiency, SCID, DiGeorge, Bruton - CVID requires IgG and IgA more than 2 SD BELOW the mean, but IgG is high in this stem." },
  { id: "im162", category: "Practice Vignettes", q: "47M farmer with a nose nodule; biopsy shows invasive melanoma with features of regression: what mechanism explains regression?", a: "'T lymphocyte-mediated cytotoxicity' - T cells recognize and destroy cancer cells (aldesleukin, recombinant IL-2, exploits this in melanoma treatment)." },
  { id: "im163", category: "Practice Vignettes", q: "20M with Crohn disease recovers on prednisone: suppression of what?", a: "T lymphocytes - steroids suppress T cell responses. Wrong answers: antibody binding, complement activity, mast cell degranulation, neutrophil function." },
  { id: "im164", category: "Practice Vignettes", q: "28F with cervical squamous cell carcinoma (HPV-18 on biopsy): which cell type is most important for killing the virally infected cells?", a: "T cells - CD8+ T cells kill virus-infected cells. Wrong answers: dendritic cells, macrophages, plasma cells." },
  { id: "im165", category: "Practice Vignettes", q: "45M with tuberculosis: which cytokine concentration is most likely increased?", a: "Interferon-gamma - IFN-gamma from CD4+ T cells stimulates macrophages to form granulomas." },
  { id: "im166", category: "Practice Vignettes", q: "25M develops rash, diarrhea, and increased LFTs one week after a bone marrow transplant: mechanism?", a: "'Donor T cells reacting against host cells' - graft-versus-host disease (usually bone marrow, sometimes liver transplants); donor T cells see host antigens as foreign." },
  { id: "im167", category: "Practice Vignettes", q: "45M, 7 weeks post bone marrow transplant with increased LFTs: which hypersensitivity type?", a: "Cell-mediated (type IV) - GVHD is cell-mediated hypersensitivity. Wrong: antibody-mediated, immediate, immune complex." },
  { id: "im168", category: "Transplant Rejection", q: "Graft vessels necrose within 15 minutes of a liver transplant - and the rejection timeline on USMLE?", a: "Preformed antibodies - hyperacute rejection (on the operating table). Acute rejection: up to several months; chronic: more than 6 months; for BOTH acute and chronic the USMLE answer is T cell response." },
  { id: "im169", category: "Practice Vignettes", q: "52M with an infiltrating parietal lobe astrocytoma: impaired activity of what is most likely responsible?", a: "p53 - often the answer for what must be mutated for cancer invasion; the effect of p53 mutation is 'defective DNA repair' (p53 normally facilitates DNA repair)." },
  { id: "im170", category: "Practice Vignettes", q: "31M with cellulitis progressing to fever, confusion, tachycardia, low BP, WBC 18,000: which two cytokines are responsible?", a: "IL-1 and TNF-alpha (fever and low BP respectively). Forced to pick one for sepsis: TNF-alpha. But if the vignette gives aspirin/ibuprofen to reduce fever, the answer is decreased PROSTAGLANDIN effect, not IL-1." },
  { id: "im171", category: "Practice Vignettes", q: "52F with breast cancer, 20-lb weight loss in a month, and no appetite: what causes the appetite loss?", a: "'Effect of cytokine' - TNF-alpha causes cachexia." },
  { id: "im172", category: "Practice Vignettes", q: "Two cell lines compared; the one transfected with an IL-2 gene generates a stronger immune response: which cell type drives the difference?", a: "T lymphocyte - IL-2 stimulates T cells." },
  { id: "im173", category: "Practice Vignettes", q: "40M with a surgically repaired wound: which inflammatory mediator is released from aggregated platelets during wound repair?", a: "Thromboxane A2." },
  { id: "im174", category: "Practice Vignettes", q: "65F with fever of 102F, muscle pain, non-productive cough, and shortness of breath: which vaccine would have prevented this?", a: "Influenza virus vaccine." },
  { id: "im175", category: "Practice Vignettes", q: "20M with fever, non-productive cough, pale conjunctivae, and a blood sample that agglutinates while awaiting transport: which antibody isotype?", a: "IgM - Mycoplasma pneumoniae causing atypical pneumonia plus cold autoimmune hemolytic anemia; IgM targets RBCs and agglutination occurs below 37C (can also be caused by CMV; warm AIHA is IgG, classically from CLL)." },
  { id: "im176", category: "Practice Vignettes", q: "61M goes hiking and develops linear vesicles on his leg: activation of which cell type?", a: "T cells - contact dermatitis (type IV hypersensitivity) from poison ivy/sumac; 'linear vesicles' is HY for brushing past weeds." },
  { id: "im177", category: "Practice Vignettes", q: "A cell line engineered to produce an inactive form of caspase: what is the most likely result?", a: "Continued proliferation of cells - caspases enable apoptosis." },
  { id: "im178", category: "Practice Vignettes", q: "50F flow cytometry: CD3 50%, CD4 40%, CD8 10%, CD20 50%, surface kappa 48%, lambda 3% - what most predicts clonal lymphoid proliferation?", a: "The surface kappa/lambda ratio. CD3 = T cells, CD20 = B cells (50/50 split here), CD4/CD8 are T cell subsets (80/20 of the T cells); kappa and lambda are B-cell light chains whose ratio skews heavily in leukemia/lymphoma. CD19 is the other key B cell marker; rituximab targets CD20." },
  { id: "im179", category: "Practice Vignettes", q: "4F with bloody diarrhea from Salmonella: which factor most recruits neutrophils to intestinal cells?", a: "IL-8 (neutrophilic chemotactic molecules include IL-8, kallikrein, platelet-activating factor, C5a, LTB-4, bacterial products)." },
  { id: "im180", category: "Practice Vignettes", q: "72M with fever 101, WBC 15,000, and a patchy infiltrate on CXR: which endogenous chemoattractant recruits leukocytes to the inflammation?", a: "C5a. Ignore distractors like filamin or N-formyl methionine terminal peptides." },
  { id: "im181", category: "Practice Vignettes", q: "2-month-old girl, feeding and developing well, temp 99.8F, normal counts except neutrophils 5%: diagnosis?", a: "Congenital neutropenia - neutrophils should be 50-55%; asked on the NBME." },
  { id: "im182", category: "Practice Vignettes", q: "22F with vesicular lesions on the lower lip: recurrences arise from viral latency where?", a: "Sensory neurons (HSV latency in the trigeminal ganglion)." },
  { id: "im183", category: "Practice Vignettes", q: "4F with fever, crackles/rhonchi, and CXR showing dextrocardia with a right-sided gastric bubble: deficiency of what?", a: "Dynein - primary ciliary dyskinesia (Kartagener syndrome): situs inversus, sinopulmonary infections, immotile sperm / ectopic pregnancy. The answer can also be 'dynein arm' or 'cilium.'" },
  { id: "im184", category: "Practice Vignettes", q: "4M with lymphadenopathy, NO granulomas on biopsy, acid-fast M. avium intracellulare, and normal immunoglobulins/B/T cells: defective expression of what?", a: "The interferon-gamma receptor - IFN-gamma is needed to form granulomas." },
  { id: "im185", category: "Practice Vignettes", q: "60F with fever, night sweats, positive PPD: organisms on sputum culture are inside which cells?", a: "Macrophages - TB is phagocytosed by alveolar macrophages. T cells is the wrong answer; they facilitate granulomas but don't harbor the organisms." },
  { id: "im186", category: "Practice Vignettes", q: "28F with AIDS develops tuberculosis: which cell type has deficient function in the tuberculous lung areas?", a: "Macrophages - CD4+ T cells normally activate macrophages via IFN-gamma, and macrophages stimulate CD4+ T cells via IL-12 (the loop breaks in AIDS). Wrong: eosinophils, neutrophils, fibroblasts, Langerhans cells." },
  { id: "im187", category: "Practice Vignettes", q: "29M, PPD positive, improves when given IFN-gamma: diagnosis?", a: "IL-12 receptor deficiency - the macrophage IL-12 → CD4+ IFN-gamma → macrophage granuloma loop is broken, increasing TB susceptibility; IFN-gamma bypasses the defect." },
  { id: "im188", category: "Practice Vignettes", q: "2-month-old girl given a vaccine that converts T cell-independent antigens into T cell-dependent ones: which vaccine?", a: "Haemophilus influenzae type B (HiB). Its polysaccharide capsule alone won't be expressed on MHC, so it is conjugated to a protein, enabling a T cell response." },
  { id: "im189", category: "Practice Vignettes", q: "2M with a scaly seborrheic eruption (scalp, palms, diaper), hepatosplenomegaly, lymphadenopathy, lytic skull lesions, tennis racquet-shaped granules on biopsy, CD1a positive: the abnormal cells derive from what?", a: "Dendritic cells - Langerhans cell histiocytosis (Langerhans cells are skin dendritic cells; the granules are Birbeck granules). Dendritic cells are APCs that travel to lymph nodes to interact with B and T cells." },
  { id: "im190", category: "Practice Vignettes", q: "34M with chronic Hep C: what mechanism best describes the hepatic damage?", a: "'Cytotoxic T cell response' - NOT direct viral cytopathic effects. Hepatitis viruses (except Hep D) damage the liver mainly by inducing a T cell-mediated response." },
  { id: "im191", category: "Practice Vignettes", q: "26M with lower back pain worse in the morning that improves through the day plus an eczematoid forehead lesion: what will be seen?", a: "HLA-B27 positivity - PAIR: Psoriasis, Ankylosing spondylitis, IBD, Reactive arthritis. Never choose HLA-B27 for diagnostic purposes; it is the immunologic link for the PAIR conditions." },
  { id: "im192", category: "Practice Vignettes", q: "14M with an intra-abdominal mass and chylothorax; biopsy shows a 'starry sky appearance'; an arrow points to a macrophage - what process is occurring?", a: "Apoptosis. Burkitt lymphoma (jaw or intra-abdominal): 'starry sky' = lymphocytes with interspersed TINGIBLE BODY macrophages - macrophages in germinal centers full of apoptotic debris. It's on the NBME." },
  { id: "im193", category: "Practice Vignettes", q: "47M with CF, months of immunosuppression after bilateral lung transplant, now higher fasting glucose: why?", a: "Adverse effect of tacrolimus - a HY drug that causes diabetes. Tacrolimus binds FK506 → decreases calcineurin → decreases IL-2 transcription (cyclosporin also decreases IL-2 transcription; sirolimus decreases responsiveness to IL-2 instead)." },
  { id: "im194", category: "Practice Vignettes", q: "42M gets an IM antibiotic and three days later develops a rash at the injection site: hypersensitivity type?", a: "Type III - Arthus reaction: localized skin reaction from immune complex deposition, distinguishable from type I because type III appears 3-5 days after exposure. Arthus is a localized form of serum sickness." },
  { id: "im195", category: "Practice Vignettes", q: "16F starts TMP/SMX for a UTI and three days later has polyarthritis: hypersensitivity type?", a: "Type III - serum sickness from the sulfa drug (also caused by Hep B/C, rubella, Yersinia, Chlamydia infections). Unlike localized Arthus, serum sickness often presents as arthritis and erythema nodosum (panniculitis of the shins)." },
  { id: "im196", category: "Practice Vignettes", q: "17M with leukemia; neoplastic cells express TCR beta-chain D and J segments but NOT CD4 or CD8: what best refers to these cells?", a: "'T cell thymocytes localized to the thymic cortex' - T cell precursors enter the cortex CD4/CD8 double-negative before becoming double-positive. Pedantic but asked on NBME." },
  { id: "im197", category: "Immunosuppressants", q: "Cyclosporine versus tacrolimus versus sirolimus: binding sites and effect on IL-2?", a: "Cyclosporine binds cyclophilin; tacrolimus binds FK506; both decrease intracellular calcineurin → decreased IL-2 TRANSCRIPTION. Sirolimus binds mTOR → decreased IL-2 RESPONSIVENESS (no calcineurin effect)." },
  { id: "im198", category: "Immunosuppressants", q: "Cyclosporine/tacrolimus/sirolimus adverse effects: diabetes, nephrotoxicity, neurotoxicity?", a: "Diabetes: tacrolimus (highest yield) and sirolimus, NOT cyclosporine. Nephrotoxic + neurotoxic: cyclosporine and tacrolimus, not sirolimus. Other HY: cyclosporine → gingival hyperplasia, HTN, hypertrichosis; sirolimus → dyslipidemia." },
  { id: "im199", category: "Monoclonal Antibodies", q: "Infliximab, adalimumab, etanercept: target, use, and the odd one out?", a: "Target soluble TNF-alpha for severe RA and IBD. Etanercept is the odd one out: it is a recombinant TNF-alpha RECEPTOR that mops up TNF-alpha, whereas the others are monoclonal antibodies against TNF-alpha." },
  { id: "im200", category: "Monoclonal Antibodies", q: "Rituximab, trastuzumab, abciximab: targets, uses, HY points?", a: "Rituximab: CD20 on B cells, for lymphoma - increased risk of PML. Trastuzumab: HER2/neu, for HER2(+) breast cancer - cardiotoxic. Abciximab: platelet GpIIb/IIIa, for PCI - students often confuse the name with adalimumab." },
  { id: "im201", category: "Monoclonal Antibodies", q: "Omalizumab and denosumab?", a: "Omalizumab: anti-IgE, for severe asthma with increased IgE. Denosumab: anti-RANKL, for advanced osteoporosis." },
  { id: "im202", category: "Monoclonal Antibodies", q: "Palivizumab, natalizumab, tocilizumab?", a: "Palivizumab: RSV F protein, prevents RSV syncytia formation in very rare cases - always the wrong answer for RSV treatment on USMLE (choose 'supportive care' - just know the drug exists and its MOA). Natalizumab: anti-alpha-4-integrin, for MS - increased risk of PML. Tocilizumab: IL-6 receptor, for severe RA." },
  { id: "im203", category: "Monoclonal Antibodies", q: "Basilixumab and eculizumab?", a: "Basilixumab: IL-2 receptor, for transplant rejection (daclizumab was another anti-IL-2R mAb once used for MS, now discontinued). Eculizumab: complement protein C5, for PNH - the lowest yield in the chart." },
];
export default immunoQuestions;
